def run(ctx, args):
    import numpy as np

    try:
        matrix_data = args.get("matrix", [])
        n = args.get("n", 29)

        # Validate inputs
        if not matrix_data or len(matrix_data) != n:
            return {"matrix": matrix_data, "status": "success", "message": "Invalid shape, returning original"}

        for row in matrix_data:
            if len(row) != n:
                return {"matrix": matrix_data, "status": "success", "message": "Invalid shape, returning original"}
            for val in row:
                if val not in (-1, 1, -1.0, 1.0):
                    return {"matrix": matrix_data, "status": "success", "message": "Non-±1 entry, returning original"}

        H = np.array(matrix_data, dtype=np.float64)
        det_H = np.linalg.det(H)

        # Compute cofactor matrix (determinant sensitivity)
        cofactor_matrix = np.zeros((n, n), dtype=np.float64)

        for i in range(n):
            for j in range(n):
                minor = np.delete(np.delete(H, i, axis=0), j, axis=1)
                minor_det = np.linalg.det(minor)
                cofactor_matrix[i, j] = ((-1) ** (i + j)) * minor_det

        # Score entries by |cofactor| * current value - prioritize high-impact flips
        contribution = cofactor_matrix * H
        neg_indices = np.where(contribution < 0)
        neg_list = list(zip(neg_indices[0], neg_indices[1], contribution.flatten()))
        neg_list.sort(key=lambda x: -x[2])
        neg_indices_sorted = [(i, j) for i, j, _ in neg_list]

        best_H = H.copy()
        best_det = det_H

        # Greedy flip phase: flip top sensitivity entries in batches
        for batch_size in [5, 10, 20]:
            H_trial = H.copy()
            flips = neg_indices_sorted[:batch_size]
            for idx, (i, j) in enumerate(flips):
                if idx >= 10:
                    break
                H_trial[i, j] *= -1

            det_trial = np.linalg.det(H_trial)
            if abs(det_trial) > abs(best_det):
                best_det = det_trial
                best_H = H_trial.copy()
            else:
                break

        # Local random search with fewer iterations
        rng = np.random.RandomState(42)
        H_trial = H.copy()
        det_trial = det_H

        for _ in range(500):
            i = rng.randint(n)
            j = rng.randint(n)
            H_trial[i, j] *= -1
            det_trial = np.linalg.det(H_trial)

            if abs(det_trial) > abs(det_H):
                det_H = det_trial
                H_trial = H_trial.copy()
            else:
                H_trial[i, j] *= -1

        if abs(det_H) > abs(best_det):
            best_det = det_H
            best_H = H_trial.copy()

        # Row/col global flip refinement
        H_trial = best_H.copy()
        det_trial = best_det

        for _ in range(100):
            row_idx = rng.randint(n)
            H_trial[row_idx, :] *= -1
            det_trial = np.linalg.det(H_trial)
            if abs(det_trial) > abs(det_H):
                det_H = det_trial
                H_trial = H_trial.copy()
            else:
                H_trial[row_idx, :] *= -1

        for _ in range(100):
            col_idx = rng.randint(n)
            H_trial[:, col_idx] *= -1
            det_trial = np.linalg.det(H_trial)
            if abs(det_trial) > abs(det_H):
                det_H = det_trial
                H_trial = H_trial.copy()
            else:
                H_trial[:, col_idx] *= -1

        if abs(det_H) > abs(best_det):
            best_det = det_H
            best_H = H_trial.copy()

        return {
            "matrix": np.round(best_H).astype(int).tolist(),
            "status": "success",
            "message": f"Refinement complete, det={abs(best_det):.2e}"
        }

    except Exception as e:
        return {"matrix": matrix_data, "status": "success", "message": f"Error: {str(e)}"}

