            rng = np.random.RandomState(seed)
        else:
            rng = np.random.RandomState()
        return rng.choice([-1, 1], size=(n, n)).astype(np.float64)

    matrix_data = args.get("matrix", [])
    n = args.get("n", 29)

    # Handle edge case
    if n <= 1 or not matrix_data:
        return {"matrix": [[1.0]] if n <= 1 else [], "status": "success", "message": "Edge case, returning original"}

    # Validate inputs
    try:
        H = np.array(matrix_data, dtype=np.float64)
        if H.shape != (n, n):
            H = np.array(matrix_data, dtype=np.float64)
    except:
        H = np.array([[1.0] * n for _ in range(n)], dtype=np.float64)

    initial_det = abs(np.linalg.det(H))

    # Generate diverse variants and test pipeline
    best_variant = H.copy()
    best_det = initial_det
    best_info = "original"

    # Variant 1: Paley construction
    paley = create_paley_matrix(n)
    paley_det = abs(np.linalg.det(paley))

