        if det_trial > best_det:
            best_det = det_trial
            best_variant = trial.copy()
            best_info += "_flip"
            refined = trial.copy()
        else:
            # Revert without updating trial
            pass

    # Check if we improved over original
    if best_det > initial_det:
        return {
            "matrix": np.round(best_variant).astype(int).tolist(),
            "status": "success",
            "message": f"Best: {best_info}, det={best_det:.2e}"
        }
