def run(ctx, args):
    import numpy as np

    n = args.get("n", 29)
    matrix_data = args.get("matrix", [])

    if n <= 1 or not matrix_data or len(matrix_data) != n:
        return {"matrix": [[1.0]] if n == 1 else [], "status": "success", "message": "Edge case"}

    try:
        H = np.array(matrix_data, dtype=np.float64)
        if H.shape != (n, n):
            H = np.array([[1.0] * n for _ in range(n)], dtype=np.float64)
    except:
        H = np.array([[1.0] * n for _ in range(n)], dtype=np.float64)

    initial_det = abs(np.linalg.det(H))

    # Variants: Paley, random seeds, and structured padding
    def create_paley(n):
        if n < 3:
            return np.ones((n, n), dtype=np.float64)
        qres = set((i*i) % n for i in range(1, n))
        return np.array([[1 if (i-j)%n == 0 or (i-j)%n in qres else -1 for j in range(n)] for i in range(n)], dtype=np.float64)

    def apply_padding(H28):
        if H28.shape != (28, 28) or n < 29:
            return H28.copy()
        H29 = np.zeros((n, n), dtype=np.float64)
        H29[:28, :28] = H28
        H29[28, 28] = 1
        H29[28, :28] = np.ones(28)
        H29[:28, 28] = np.ones(28)
        return H29

    best = H.copy()
    best_det = initial_det

    # Try Paley
    paley = create_paley(n)
    pdet = abs(np.linalg.det(paley))
    if pdet > best_det:
        best, best_det = paley, pdet

    # Try random matrices with different seeds
    for seed in [0, 1, 2, 3, 4]:
        rand_m = np.random.RandomState(seed).choice([-1, 1], size=(n, n)).astype(np.float64)
        rdet = abs(np.linalg.det(rand_m))
        if rdet > best_det:
            best, best_det = rand_m, rdet

    # Try structured padding variants
    H28_base = create_paley(n - 1) if n > 8 else np.ones((min(n-1, 7), min(n-1, 7)), dtype=np.float64)
    for seed in [0, 1, 2, 3, 4]:
        H28 = np.random.RandomState(seed).choice([-1, 1], size=(28, 28)).astype(np.float64) if 28 <= min(n-1, 28) else H28_base
        padded = apply_padding(H28)
        pdet = abs(np.linalg.det(padded))
        if pdet > best_det:
            best, best_det = padded, pdet

    # Simple refinement: flip best contributors
    contrib = best * best / (np.linalg.det(best) + 1e-8)
    neg_idx = np.argwhere(contrib < 0)
    for i, j in neg_idx[:5]:
        trial = best.copy()
        trial[i, j] *= -1
        tdet = abs(np.linalg.det(trial))
        if tdet > best_det:
            best, best_det = trial, tdet

    return {"matrix": np.round(best).astype(int).tolist(), "status": "success", "message": f"Best: det={best_det:.2e}"}

