            H = np.array(matrix_data, dtype=np.float64)
    except:
        H = np.array([[1.0] * n for _ in range(n)], dtype=np.float64)

    initial_det = abs(np.linalg.det(H))

    # Generate diverse variants and test pipeline
    best_variant = H.copy()
    best_det = initial_det
    best_info = "original"

    # Variant 1: Paley construction
    paley = create_paley_matrix(n)
    paley_det = abs(np.linalg.det(paley))

    if paley_det > best_det:
        best_variant = paley.copy()
        best_det = paley_det
        best_info = "paley"

    # Variant 2: Random matrix
    random_m = create_random_matrix(n, seed=42)
    random_det = abs(np.linalg.det(random_m))

    if random_det > best_det:
        best_variant = random_m.copy()
        best_det = random_det
        best_info = "random"

    # Apply simple refinement to best variant (lightweight version)
    refined = best_variant.copy()
    n_val = int(n)

    # Single-element flip refinement (limited)
    for _ in range(200):
        i = np.random.randint(n_val)
        j = np.random.randint(n_val)
        trial = refined.copy()
        trial[i, j] *= -1
        det_trial = abs(np.linalg.det(trial))
        if det_trial > best_det:
            best_det = det_trial
            best_variant = trial.copy()
            best_info += "_flip"
            refined = trial.copy()
        else:
            # Revert without updating trial
            pass

    # Check if we improved over original
    if best_det > initial_det:
        return {
            "matrix": np.round(best_variant).astype(int).tolist(),
            "status": "success",
            "message": f"Best: {best_info}, det={best_det:.2e}"
        }
    else:
        return {
            "matrix": matrix_data if isinstance(matrix_data, list) else np.round(H).astype(int).tolist(),
            "status": "success",
            "message": f"No improvement, det={best_det:.2e}"
        }

