def run(ctx, args):
    import numpy as np

    try:
        matrix_data = args.get("matrix", [])
        n = args.get("n", 29)

        # Validate
        if not matrix_data or len(matrix_data) != n:
            return {"matrix": matrix_data, "status": "success", "message": "Invalid shape"}

        for row in matrix_data:
            if len(row) != n:
                return {"matrix": matrix_data, "status": "success", "message": "Invalid shape"}

        H = np.array(matrix_data, dtype=np.float64)
        det_H = np.linalg.det(H)
        best_H = H.copy()
        best_det = det_H

        # Greedy row permutation
        rows = list(range(n))
        for perm in range(20):
            H_trial = H.copy()
            rng = np.random.RandomState(42 + perm)
            rows_shuffled = rng.permutation(n)
            H_trial[np.ix_(rows_shuffled, list(range(n)))] = H_trial[np.ix_(rows, list(range(n)))]
            det_trial = np.linalg.det(H_trial)
            if abs(det_trial) > abs(best_det):
                best_det = det_trial
                best_H = H_trial.copy()

        # Greedy column permutation
        cols = list(range(n))
        for perm in range(20):
            H_trial = H.copy()
            rng = np.random.RandomState(42 + perm + 100)
            cols_shuffled = rng.permutation(n)
            H_trial[np.ix_(list(range(n)), cols_shuffled)] = H_trial[np.ix_(list(range(n)), cols)]
            det_trial = np.linalg.det(H_trial)
            if abs(det_trial) > abs(best_det):
                best_det = det_trial
                best_H = H_trial.copy()

        # Combined row+col permutations
        H_trial = best_H.copy()
        best_det2 = best_det
        for perm in range(10):
            rows_shuffled = np.random.RandomState(42 + perm).permutation(n)
            cols_shuffled = np.random.RandomState(42 + perm + 100).permutation(n)
            H_trial[np.ix_(rows_shuffled, cols_shuffled)] = best_H[np.ix_(rows, cols)]
            det_trial = np.linalg.det(H_trial)
            if abs(det_trial) > abs(best_det2):
                best_det2 = det_trial
                best_H = H_trial.copy()

        return {
            "matrix": np.round(best_H).astype(int).tolist(),
            "status": "success",
            "message": f"Permutation search complete, det={abs(best_det2):.2e}"
        }
    except Exception as e:
        return {"matrix": matrix_data, "status": "success", "message": f"Error: {str(e)}"}

