                        d = (i - j) % n
                        m[i, j] = 1 if d == 0 or d in qr else -1
                if len(matrices) < num_matrices:
                    matrices.append(m)

        # 3. Paley with shifts
        if n % 4 == 0 and len(matrices) < num_matrices:
