                        d = (i - j) % n
                        m[i, j] = 1 if d == 0 or d in qr else -1
                if len(matrices) < num_matrices:
                    matrices.append(m)

        # 4. Tensor products (powers of 2)
        if n % 2 == 0 and len(matrices) < num_matrices:
            H2 = np.array([[1, 1], [1, -1]])
            H4 = np.kron(H2, H2)
